import type { ComponentProps } from "react";
import {
  type KnobProps,
  knobVariants,
} from "@/components/audio-ui/knob";
import { cn } from "@/lib/utils";
import { START_ANGLE, SWEEP_ANGLE } from "../../knob/knob";
import { Knob as KnobPrimitive } from "@/components/audio-ui/knob/react";

/** The printed scale: eleven ticks along the sweep, longer at both ends and in the middle. */
const TICKS = Array.from({ length: 11 }, (_, index) => ({
  angle: START_ANGLE + (index / 10) * SWEEP_ANGLE,
  index,
  long: index % 5 === 0,
}));

function PrintedScale() {
  return (
    <svg
      aria-hidden="true"
      className="pointer-events-none absolute -inset-2 size-[calc(100%+1rem)] text-[color:var(--audio-print,var(--muted-foreground))]"
      viewBox="0 0 100 100"
    >
      {TICKS.map(({ angle, index, long }) => (
        <line
          key={index}
          stroke="currentColor"
          strokeWidth={long ? 2 : 1}
          transform={`rotate(${angle} 50 50)`}
          x1={50}
          x2={50}
          y1={0}
          y2={long ? 7 : 4}
        />
      ))}
    </svg>
  );
}

/** The grip line, on the thumb, which the knob turns: from near the center to the rim of the cap. */
function GripThumb(props: ComponentProps<"div">) {
  return (
    <div {...props}>
      {props.children}
      <span
        aria-hidden="true"
        className="absolute top-[18%] left-1/2 h-[30%] w-0.5 -translate-x-1/2 rounded-full bg-[color:var(--audio-print,var(--foreground))]"
      />
    </div>
  );
}

const gripThumb = (props: ComponentProps<"div">) => <GripThumb {...props} />;

/**
 * The Hardware face of the knob: a dark socket, a matte cap lit from above, a
 * grip line that turns with it and a printed scale. Same props as `Knob`.
 */
export function HardwareKnob({
  "aria-describedby": ariaDescribedBy,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  className,
  dragMode,
  editableValue = false,
  formatValue,
  marks,
  size,
  valueLabel = "auto",
  ...props
}: KnobProps) {
  const hasLabels = marks?.some(
    (mark) => typeof mark !== "number" && mark.label !== undefined
  );
  return (
    <KnobPrimitive.Root
      className={cn(
        knobVariants({ size }),
        "group/knob m-2",
        hasLabels && "m-5",
        valueLabel !== "hidden" && (hasLabels ? "mb-12" : "mb-8"),
        className
      )}
      data-slot="knob"
      dragMode={dragMode}
      {...props}
    >
      {marks ? null : <PrintedScale />}
      <KnobPrimitive.Control
        className="relative isolate flex size-full cursor-grab touch-none select-none rounded-full outline-none [clip-path:circle(50%_at_50%_50%)] bg-[color:var(--audio-socket,var(--secondary))] shadow-[inset_0_1px_3px_rgb(0_0_0/0.5)] focus-visible:outline-none active:cursor-grabbing data-disabled:pointer-events-none data-[drag-mode=vertical]:cursor-ns-resize data-disabled:opacity-50"
        data-slot="knob-control"
      >
        <div
          className="audio-cap absolute inset-[12%] rounded-full"
          data-slot="knob-body"
        />
        <KnobPrimitive.Indicator
          className="pointer-events-none absolute inset-0 z-1 block size-full text-[color:var(--audio-accent,var(--primary))]"
          data-slot="knob-arc"
          strokeWidth={1.5}
        />
        <KnobPrimitive.Thumb
          aria-describedby={ariaDescribedBy}
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          className="pointer-events-none absolute inset-0 z-2"
          data-slot="knob-thumb"
          getAriaValueText={
            formatValue ? (_formatted, value) => formatValue(value) : undefined
          }
          render={gripThumb}
        />
      </KnobPrimitive.Control>
      {marks?.map((mark) => {
        const { label, value } =
          typeof mark === "number" ? { label: undefined, value: mark } : mark;
        return (
          <KnobPrimitive.Mark key={value} value={value}>
            <span className="-top-2.5 absolute left-1/2 h-1.5 w-px -translate-x-1/2 bg-[color:var(--audio-print,var(--muted-foreground))]" />
            {label === undefined ? null : (
              <span className="audio-print -top-6 absolute left-1/2 -translate-x-1/2 [rotate:calc(var(--knob-mark-angle)*-1)]">
                {label}
              </span>
            )}
          </KnobPrimitive.Mark>
        );
      })}
      {valueLabel === "hidden" ? null : (
        <KnobPrimitive.Value
          className={cn(
            "rounded-[min(var(--radius-sm),6px)] bg-[color:var(--audio-readout,var(--foreground))] px-1.5 py-0.5 font-medium text-[10px] text-[color:var(--audio-readout-ink,var(--background))] tabular-nums leading-none shadow-sm absolute top-full left-1/2 z-10 mt-1 -translate-x-1/2 whitespace-nowrap",
            editableValue ? "cursor-text" : "pointer-events-none",
            hasLabels && "mt-6",
            valueLabel === "auto" &&
              "opacity-0 transition-opacity duration-150 ease-out group-hover/knob:opacity-100 group-has-focus-visible/knob:opacity-100 group-data-dragging/knob:opacity-100 data-editing:opacity-100 motion-reduce:transition-none"
          )}
          data-slot="knob-value"
          editable={editableValue}
        >
          {({ formatted, value }) =>
            formatValue ? formatValue(value) : formatted
          }
        </KnobPrimitive.Value>
      )}
    </KnobPrimitive.Root>
  );
}

import type { ComponentProps, ReactNode } from "react";
import type {
  FaderMark,
  FaderProps,
} from "@/components/audio-ui/fader";
import { cn } from "@/lib/utils";
import { DEFAULT_MAX, DEFAULT_MIN } from "../../fader/fader";
import { Fader as FaderPrimitive } from "@/components/audio-ui/fader/react";

/** The graduations of a fader in dB, down to its floor. */
const DECIBELS = [6, 0, -6, -12, -24, -48];
/** A range that reaches this low reads as one in dB. */
const DECIBEL_FLOOR = -48;
/** A floor this low is printed as silence. */
const SILENCE = -60;

/** The scale of a fader that was given none: dB for a range in dB, its ends and middle otherwise. */
function printedMarks(min: number, max: number): FaderMark[] {
  if (min <= DECIBEL_FLOOR && max <= 24) {
    const levels = DECIBELS.filter((level) => level > min && level <= max);
    return [...levels, { label: min <= SILENCE ? "-∞" : min, value: min }];
  }
  return [min, (min + max) / 2, max].map((value) => ({ label: value, value }));
}

const markOf = (mark: FaderMark): { label?: ReactNode; value: number } =>
  typeof mark === "number" ? { value: mark } : mark;

const SIZES = {
  default: {
    horizontal: "h-7 w-11",
    vertical: "h-11 w-7",
  },
  lg: { horizontal: "h-8 w-12", vertical: "h-12 w-8" },
  sm: { horizontal: "h-6 w-9", vertical: "h-9 w-6" },
};

const RIBS = [0, 1, 2, 3, 4];

/** The cap, ribbed across the travel, its middle rib in the accent. */
function RibbedThumb(
  props: ComponentProps<"div"> & { "data-orientation"?: string }
) {
  const vertical = props["data-orientation"] !== "horizontal";
  return (
    <div {...props}>
      <span
        aria-hidden="true"
        className={cn(
          "audio-cap absolute inset-0 flex items-center justify-center gap-[3px] rounded-[3px]",
          vertical ? "flex-col" : "flex-row"
        )}
      >
        {RIBS.map((rib) => (
          <span
            className={cn(
              "rounded-full",
              vertical ? "h-px w-3/4" : "h-3/4 w-px",
              rib === 2
                ? "bg-[color:var(--audio-accent,var(--primary))]"
                : "bg-black/30"
            )}
            key={rib}
          />
        ))}
      </span>
      {props.children}
    </div>
  );
}

const ribbedThumb = (props: ComponentProps<"div">) => (
  <RibbedThumb {...props} />
);

/**
 * The Hardware face of the fader: a narrow inset slot, a ribbed cap and a
 * printed scale. Same props as `Fader`; `thumbMarks` is the digital cap's.
 */
export function HardwareFader({
  "aria-describedby": ariaDescribedBy,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  className,
  editableValue = false,
  formatValue,
  marks,
  max = DEFAULT_MAX,
  min = DEFAULT_MIN,
  orientation = "vertical",
  size,
  thumbMarks: _thumbMarks,
  valueLabel = "auto",
  ...props
}: FaderProps) {
  const vertical = orientation === "vertical";
  return (
    <FaderPrimitive.Root
      className={cn(
        "group/fader relative data-disabled:cursor-not-allowed data-[orientation=horizontal]:w-full data-[orientation=vertical]:h-full data-[orientation=horizontal]:pb-6 data-[orientation=vertical]:ps-10",
        className
      )}
      max={max}
      min={min}
      orientation={orientation}
      {...props}
    >
      <FaderPrimitive.Control className="relative flex w-full touch-none select-none items-center transition-opacity duration-150 ease-out motion-reduce:transition-none data-disabled:pointer-events-none data-[orientation=vertical]:h-full data-[orientation=horizontal]:min-h-11 data-[orientation=vertical]:min-h-[var(--fader-min-height,10rem)] data-[orientation=horizontal]:w-full data-[orientation=horizontal]:min-w-32 data-[orientation=vertical]:w-11 data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-center data-disabled:opacity-50">
        <FaderPrimitive.Track
          className="audio-groove relative grow cursor-pointer select-none rounded-full data-[orientation=horizontal]:h-1 data-[orientation=vertical]:w-1 data-[orientation=horizontal]:w-full"
          data-slot="fader-track"
        />
        <div
          aria-hidden="true"
          className={cn(
            "pointer-events-none absolute",
            vertical
              ? "inset-y-0 end-[calc(50%+1rem)]"
              : "inset-x-0 top-[calc(50%+1rem)]"
          )}
          data-slot="fader-scale"
        >
          {(marks ?? printedMarks(min, max)).map((mark) => {
            const { label, value } = markOf(mark);
            return (
              <FaderPrimitive.Mark
                className={cn(
                  "flex items-center gap-1",
                  vertical
                    ? "end-0 translate-y-1/2 flex-row"
                    : "-translate-x-1/2 flex-col-reverse"
                )}
                key={value}
                value={value}
              >
                {label === undefined ? null : (
                  <span className="audio-print">{label}</span>
                )}
                <span
                  className={cn(
                    "bg-[color:var(--audio-print,var(--muted-foreground))]",
                    vertical ? "h-px w-1.5" : "h-1.5 w-px"
                  )}
                />
              </FaderPrimitive.Mark>
            );
          })}
        </div>
        <FaderPrimitive.Thumb
          aria-describedby={ariaDescribedBy}
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          className={cn(
            "absolute z-10 block shrink-0 cursor-grab select-none rounded-[3px] outline-none has-focus-visible:ring-3 has-focus-visible:ring-ring/50 active:cursor-grabbing data-disabled:pointer-events-none",
            SIZES[size ?? "default"][orientation]
          )}
          data-slot="fader-thumb"
          getAriaValueText={
            formatValue ? (_formatted, value) => formatValue(value) : undefined
          }
          render={ribbedThumb}
        >
          {valueLabel === "hidden" ? null : (
            <FaderPrimitive.Value
              className={cn(
                "rounded-[min(var(--radius-sm),6px)] bg-[color:var(--audio-readout,var(--foreground))] px-1.5 py-0.5 font-medium text-[10px] text-[color:var(--audio-readout-ink,var(--background))] tabular-nums leading-none shadow-sm absolute z-20 whitespace-nowrap",
                editableValue ? "cursor-text" : "pointer-events-none",
                vertical
                  ? "start-full top-1/2 ms-2 -translate-y-1/2"
                  : "bottom-full left-1/2 mb-2 -translate-x-1/2",
                valueLabel === "auto" &&
                  "opacity-0 transition-opacity duration-150 ease-out group-hover/fader:opacity-100 group-has-focus-visible/fader:opacity-100 group-has-data-dragging/fader:opacity-100 data-editing:opacity-100 motion-reduce:transition-none"
              )}
              data-slot="fader-value"
              editable={editableValue}
            >
              {({ formatted, value }) =>
                formatValue ? formatValue(value) : formatted
              }
            </FaderPrimitive.Value>
          )}
        </FaderPrimitive.Thumb>
      </FaderPrimitive.Control>
    </FaderPrimitive.Root>
  );
}

import {
  type ComponentProps,
  createContext,
  use,
  useEffect,
  useRef,
} from "react";
import type { MeterProps } from "@/components/audio-ui/meter";
import { VU_DIAL } from "@/components/audio-ui/needle-meter";
import { cn } from "@/lib/utils";
import {
  createVuBallistics,
  FLOOR_DB,
} from "@/components/audio-ui/meter/ballistics";
import { Meter as MeterPrimitive } from "@/components/audio-ui/meter/react";

/** The level, in dB, that reads 0 VU: the alignment common for digital audio. */
const REFERENCE = -18;

const SIZES = { default: "w-44", lg: "w-60", sm: "w-32" };

/** Reads a channel's level now, in dB. */
const Levels = createContext<(channel: number) => number>(() => FLOOR_DB);

const decibels = (formattedValue: string) => `${formattedValue} dB`;

/** The dial of one channel: its needle follows the level with the VU ballistics, turned outside React. */
function Dial({
  channel,
  ...props
}: ComponentProps<"div"> & { channel: number }) {
  const read = use(Levels);
  const needle = useRef<SVGLineElement>(null);

  useEffect(() => {
    const ballistics = createVuBallistics();
    let frame = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const vu = ballistics.step(
        read(channel) - REFERENCE,
        (now - last) / 1000
      );
      last = now;
      if (needle.current) {
        needle.current.style.transform = `rotate(${VU_DIAL.angleOf(vu)}deg)`;
      }
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [channel, read]);

  return (
    <div {...props}>
      <svg aria-hidden="true" className="block w-full" viewBox="0 0 200 118">
        <path
          className="stroke-[var(--audio-screen-ink,var(--muted-foreground))]"
          d={VU_DIAL.arc}
          fill="none"
        />
        <path
          className="stroke-[var(--audio-clip,var(--destructive))]"
          d={VU_DIAL.zone}
          fill="none"
          strokeWidth={3}
        />
        {VU_DIAL.scale.map(({ hot, inner, label, mark, outer, text }) => (
          <g
            className={
              hot
                ? "text-[color:var(--audio-clip,var(--destructive))]"
                : "text-[color:var(--audio-screen-ink,var(--muted-foreground))]"
            }
            key={mark}
          >
            <line
              stroke="currentColor"
              strokeWidth={1.5}
              x1={inner.x}
              x2={outer.x}
              y1={inner.y}
              y2={outer.y}
            />
            <text
              className="text-[8px] tabular-nums"
              dominantBaseline="central"
              fill="currentColor"
              textAnchor="middle"
              x={text.x}
              y={text.y}
            >
              {label}
            </text>
          </g>
        ))}
        <text
          className="fill-[var(--audio-screen-ink,var(--muted-foreground))] text-[10px] tracking-widest"
          textAnchor="middle"
          x={VU_DIAL.pivot.x}
          y={68}
        >
          VU
        </text>
        <line
          className="stroke-[var(--audio-accent,var(--primary))]"
          ref={needle}
          strokeLinecap="round"
          strokeWidth={2}
          style={{
            transform: `rotate(${VU_DIAL.angleOf(Number.NEGATIVE_INFINITY)}deg)`,
            transformBox: "view-box",
            transformOrigin: `${VU_DIAL.pivot.x}px ${VU_DIAL.pivot.y}px`,
          }}
          x1={VU_DIAL.pivot.x}
          x2={VU_DIAL.tip.x}
          y1={VU_DIAL.pivot.y}
          y2={VU_DIAL.tip.y}
        />
        <circle
          className="fill-[var(--audio-cap,var(--card))]"
          cx={VU_DIAL.pivot.x}
          cy={VU_DIAL.pivot.y}
          r={7}
        />
      </svg>
      <span
        aria-hidden="true"
        className="audio-lamp group-data-clipped/channel:audio-lamp-on group-data-clipping/channel:audio-lamp-on absolute top-2 right-2 size-2"
      />
      {props.children}
    </div>
  );
}

const dial = (props: ComponentProps<"div">, { index }: { index: number }) => (
  <Dial {...props} channel={index} />
);

/**
 * The Hardware face of the meter: a needle VU dial per channel in a dark
 * screen, with a clip lamp. 0 VU is -18 dB. Same props as `Meter`; the dial
 * has the standard VU scale, so `marks`, `peakMarks` and `scale` do not draw.
 */
export function HardwareVuMeter({
  "aria-label": ariaLabel,
  className,
  marks: _marks,
  peakMarks: _peakMarks,
  size,
  source,
  value,
  ...props
}: MeterProps) {
  const held = useRef({ source, value });
  held.current = { source, value };
  const read = useRef((channel: number) => {
    const { source: live, value: given } = held.current;
    const levels = live ? live.getSnapshot().levels : given;
    return levels?.[channel] ?? FLOOR_DB;
  }).current;
  return (
    <Levels value={read}>
      <MeterPrimitive.Root
        aria-label={ariaLabel}
        className={cn("flex w-fit select-none gap-2", className)}
        data-slot="meter"
        source={source}
        value={value}
        {...props}
      >
        {({ channelCount }) =>
          Array.from({ length: channelCount }, (_, index) => index).map(
            (index) => (
              <MeterPrimitive.Channel
                aria-label={
                  ariaLabel && channelCount > 1
                    ? `${ariaLabel} ${index + 1}`
                    : ariaLabel
                }
                className={cn(
                  "group/channel audio-screen relative rounded-md p-2",
                  SIZES[size ?? "default"]
                )}
                getAriaValueText={decibels}
                index={index}
                key={index}
                render={dial}
              />
            )
          )
        }
      </MeterPrimitive.Root>
    </Levels>
  );
}
